  isProjectFileEntryName,
  joinHostPath,
  type BrowseHostResponse,
  type HostPath,
  type ProjectFolderPickerLease,
} from '../../shared'
import {
  isProjectPathExistsError,
  type Disposer,
  type ProjectHost,
} from '../project-host'
import type {
  RendererOwner,
  RendererResourceLease,
  RendererResourceScopes,
} from '../renderer-resource-scopes'

