       setPathInput(result.path.path)
       setSelectedPath(result.path.path)
       setRevealRequest({
         path: result.path.path,
         token: ++nextRevealToken.current,
       })
     } catch (reason) {
       setError(reason instanceof Error ? reason.message : String(reason))
     } finally {
       setBusy(false)
     }
   }

