       await releasePicker().catch(() => undefined)
       rememberFolder(connected.host.hostId, state.root.path)
       onOpened(state)
     } catch (reason) {
       setError(reason instanceof Error ? reason.message : String(reason))
       setBusy(false)
     }
   }

