                 <code>{selectedPath ?? 'Choose a folder from the tree'}</code>
                 {newFolderName === undefined ? (
                   <button
                     type="button"
                     disabled={busy || !selectedPath}
                     onClick={() => setNewFolderName('')}
                   >
                     New folder
