                   </form>
                 )}
               </div>
               {connectedHostId ? (
                 <DirectoryTree
                   root={hostPath(asHostId(connectedHostId), '/')}
                   rootLabel="/"
                   loadEntries={loadPickerEntries}
                   refreshVersion={treeRefreshVersion}
                   selected={
                     selectedPath
