            focusViewerPane(pane)
            if (paneTab) pinTab(paneTab.id)
            openFile(path, ******)
          }}
          onRenderedDependencies={viewer.setRenderedDependencies}
          documentReview={documentReview}
        />
      )}
    </div>
  </section>
)
return (
  <div className="app-shell">
    {projectState ? (
      <ProjectsBar
        state={projectState}
        rollups={terminalAttention.rollups}
        busy={session.busy}
